def char_swap(text, char_map):
    return "".join(char_map.get(c, c) for c in text)

def detect_adversarial(original, perturbed, threshold=0.15):
    matches = sum(1 for a, b in zip(original.lower(), perturbed.lower()) if a == b)
    similarity = round(matches / max(len(original), len(perturbed)), 4)
    diff = round(1 - similarity, 4)
    return {"similarity": similarity, "diff": diff, "flagged": diff > threshold}

original = "The quick brown fox"
char_map = {"o": "0", "i": "1", "e": "3", "a": "@"}
perturbed = char_swap(original, char_map)

print(f"Original:  {original}")
print(f"Perturbed: {perturbed}")
result = detect_adversarial(original, perturbed)
print(f"Similarity: {result['similarity']}")
print(f"Difference: {result['diff']}")
print(f"Adversarial flag: {result['flagged']}")
